export interface ErrorStackOptions {
  mode?: 'off' | 'string' | 'frames';
  normalizeNewlines?: boolean;
  trimLeadingWhitespace?: boolean;
  maxStackLines?: number;
  stripInternalFrames?: 'none' | 'node' | 'superjson' | 'node_and_superjson';
  redactPaths?: 'none' | 'basename' | 'strip_cwd';
  includeCauses?: 'none' | 'direct' | 'deep';
  maxCauseDepth?: number;
  sanitizeMessage?: boolean;
  classFilter?: string[];
}

export interface NormalizedErrorStackOptions {
  mode: 'off' | 'string' | 'frames';
  normalizeNewlines: boolean;
  trimLeadingWhitespace: boolean;
  maxStackLines?: number;
  stripInternalFrames: 'none' | 'node' | 'superjson' | 'node_and_superjson';
  redactPaths: 'none' | 'basename' | 'strip_cwd';
  includeCauses: 'none' | 'direct' | 'deep';
  maxCauseDepth: number;
  sanitizeMessage: boolean;
  classFilter: string[];
}

export function normalizeErrorStackOptions(input: unknown): NormalizedErrorStackOptions | undefined {
  if (input === null || typeof input !== 'object' || Array.isArray(input)) return undefined;
  const o = input as ErrorStackOptions;
  const validLines = o.maxStackLines === undefined || (Number.isInteger(o.maxStackLines) && o.maxStackLines > 0);
  const mode = validLines && (o.mode === 'string' || o.mode === 'frames') ? o.mode : 'off';
  const stripInternalFrames = o.stripInternalFrames === 'node' || o.stripInternalFrames === 'superjson' || o.stripInternalFrames === 'node_and_superjson' ? o.stripInternalFrames : 'none';
  const redactPaths = o.redactPaths === 'basename' || o.redactPaths === 'strip_cwd' ? o.redactPaths : 'none';
  const validDepth = o.maxCauseDepth === undefined || Number.isInteger(o.maxCauseDepth);
  const includeCauses = validDepth && (o.includeCauses === 'direct' || o.includeCauses === 'deep') ? o.includeCauses : 'none';
  return {
    mode, normalizeNewlines: o.normalizeNewlines === true,
    trimLeadingWhitespace: o.trimLeadingWhitespace !== false,
    maxStackLines: validLines ? o.maxStackLines : undefined,
    stripInternalFrames, redactPaths, includeCauses,
    maxCauseDepth: o.maxCauseDepth === undefined || !validDepth ? 16 : Math.max(0, o.maxCauseDepth),
    sanitizeMessage: o.sanitizeMessage === true,
    classFilter: Array.isArray(o.classFilter) ? [...o.classFilter] : [],
  };
}

export function sanitizeMessage(message: string): string {
  return message.replace(/https?:\/\/[^\s]+|\b[\w.+-]+@[\w.-]+\.[a-zA-Z]{2,}\b|\b(?:\d{1,3}\.){3}\d{1,3}\b/gi, '[redacted]');
}

export type Processor = (error: any) => any;

export class ErrorClassRegistry {
  private readonly processors = new Map<string, Processor>();

  register(name: string, fn: Processor): void { this.processors.set(name, fn); }
  has(name: string): boolean { return this.processors.has(name); }
  getProcessor(name: string): Processor | undefined { return this.processors.get(name); }
}

import { NormalizedErrorStackOptions } from './error-options.js';

export function normalizeStackNewlines(stack: string): string {
  return stack.replace(/\r\n?/g, '\n');
}

function linesOf(stack: string, options: NormalizedErrorStackOptions): string[] {
  const lines = (options.normalizeNewlines ? normalizeStackNewlines(stack) : stack).split('\n');
  if (options.trimLeadingWhitespace) {
    for (let i = 1; i < lines.length; i++) lines[i] = lines[i].replace(/^[\t ]+/, '');
  }
  return lines;
}

function strip(lines: string[], options: NormalizedErrorStackOptions): string[] {
  return lines.filter((line, i) => i === 0 || !(
    ((options.stripInternalFrames === 'node' || options.stripInternalFrames === 'node_and_superjson') && line.includes('node:internal')) ||
    ((options.stripInternalFrames === 'superjson' || options.stripInternalFrames === 'node_and_superjson') && /src[\\/]\/??(?:transformer|plainer|index)\.ts/.test(line))
  ));
}

function redact(lines: string[], options: NormalizedErrorStackOptions): string[] {
  if (options.redactPaths === 'none') return lines;
  const cwd = typeof process !== 'undefined' && typeof process.cwd === 'function' ? process.cwd() : '';
  return lines.map((line, i) => {
    if (i === 0) return line;
    if (options.redactPaths === 'strip_cwd') return cwd ? line.split(cwd + '/').join('').split(cwd + '\\').join('') : line;
    return line.replace(/(?:[A-Za-z]:)?(?:[\\/][^\\/\s():]+)+/g, path => path.split(/[\\/]/).pop() || path);
  });
}

export function processStackString(stack: string, options: NormalizedErrorStackOptions): string {
  let lines = redact(linesOf(stack, options), options);
  if (options.maxStackLines !== undefined) lines = lines.slice(0, options.maxStackLines);
  return strip(lines, options).join('\n');
}

export function processStackFrames(stack: string, options: NormalizedErrorStackOptions): { raw: string }[] {
  let lines = redact(strip(linesOf(stack, options), options), options);
  if (options.maxStackLines !== undefined) lines = lines.slice(0, options.maxStackLines);
  return lines.map(raw => ({ raw }));
}

